(() => { const c = window.MGD_CMS_CONFIG || {}; if (!c.url || !c.key || !window.supabase) return; const s = window.supabase.createClient(c.url, c.key); const esc = (v) => String(v || '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x])); async function refresh(){ const [{data:slides},{data:news}] = await Promise.all([s.from('mgd_slides').select('*').eq('status','published').order('sort_order'),s.from('mgd_news').select('*').eq('status','published').order('published_at',{ascending:false})]); if(slides?.length && window.slides){window.slides=slides.map(x=>({title:esc(x.title).replace(/\n/g,'<br>'),desc:x.summary,caption:'ÖNCE AHLAK VE MANEVİYAT',image:x.image_url,buttonLabel:x.button_label,buttonUrl:x.button_url})); window.slide=0; window.renderSlide?.();} if(news?.length){const cards=document.querySelector('.news-teasers'); if(cards) cards.innerHTML=news.slice(0,4).map(n=>`<article class="news-teaser"><span class="news-teaser-index">${n.category}</span><div><small>${n.published_at || ''}</small><h3>${esc(n.title)}</h3><p>${esc(n.summary)}</p></div><span class="news-teaser-arrow">↗</span></article>`).join('');}} refresh(); })();

